APP_CSS = "@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700&family=Space+Grotesk:wght@500;600;700&display=swap');\n\n:root {\n  --ink: #18232b;\n  --muted: #64747c;\n  --paper: #f4f1ea;\n  --panel: #fffdf8;\n  --surface: #fffaf0;\n  --teal: #137b73;\n  --teal-dark: #0c625c;\n  --gold: #e7a83e;\n  --red: #b54d43;\n  --line: #d9d7cc;\n  --focus: rgba(19, 123, 115, .2);\n  --radius: 6px;\n  --space-1: 8px;\n  --space-2: 14px;\n  --space-3: 20px;\n  --space-4: 28px;\n  --space-5: 40px;\n  --shadow: 0 12px 35px rgba(24, 35, 43, .06);\n}\n\n*, *::before { box-sizing: border-box; }\nhtml { min-width: 320px; }\nbody {\n  margin: 0;\n  background: radial-gradient(circle at 90% 0%, #dbeae2 0, transparent 30%), var(--paper);\n  color: var(--ink);\n  font-family: 'DM Sans', sans-serif;\n  line-height: 1.5;\n}\nh1, h2, h3, .nav-link, .table-title, .history-table-title, .score-game-title {\n  font-family: 'Space Grotesk', sans-serif;\n}\nh1, h2, h3, p { margin-top: 0; }\nh2 { margin-bottom: var(--space-3); }\nh3 { margin-bottom: var(--space-2); }\nbutton, input, select { font: inherit; }\nbutton, .btn, .form-control, .form-select { min-height: 44px; }\nbutton, .btn { border-radius: var(--radius); font-weight: 700; }\nbutton:focus-visible, input:focus-visible, select:focus-visible, .nav-link:focus-visible {\n  outline: 3px solid var(--focus);\n  outline-offset: 2px;\n}\n\n.app-shell {\n  width: min(1180px, 100%);\n  margin: 0 auto;\n  padding: 132px 24px 72px;\n}\n.intro { margin-bottom: var(--space-4); }\n.intro h1 { max-width: 720px; margin: 10px 0 var(--space-2); font-size: clamp(2.2rem, 5vw, 4.4rem); line-height: 1; }\n.intro p { max-width: 680px; color: var(--muted); font-size: 1.05rem; }\n.eyebrow { color: var(--teal); font-size: .75rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }\n\n.nav-tabs {\n  display: flex;\n  gap: 4px;\n  margin-bottom: var(--space-4);\n  border-bottom: 1px solid var(--line);\n  overflow-x: auto;\n  overflow-y: hidden;\n  scrollbar-width: thin;\n}\n.nav-tabs .nav-link { flex: 0 0 auto; padding: 12px 15px; color: var(--muted); font-weight: 700; white-space: nowrap; }\n.nav-tabs .nav-link.active { color: var(--teal); background: transparent; border-color: var(--teal); }\n.panel { margin-bottom: var(--space-3); padding: var(--space-4); background: rgba(255, 253, 248, .88); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); }\n.panel h2 { margin-bottom: var(--space-4); }\n\n.form-group { margin-bottom: var(--space-3); }\n.form-group > label, label { margin-bottom: var(--space-1); font-weight: 700; }\n.form-control, .form-select { border-color: var(--line); border-radius: var(--radius); background: #fff; color: var(--ink); }\n.btn-primary { background: var(--teal); border-color: var(--teal); }\n.btn-primary:hover { background: var(--teal-dark); border-color: var(--teal-dark); }\n.btn-success { background: var(--gold); border-color: var(--gold); color: var(--ink); }\n.action-row { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); margin-top: var(--space-3); }\n\n.player-selector { position: relative; margin: var(--space-3) 0 var(--space-4); }\n.player-selector > label { display: block; }\n#player-search { width: 100%; padding: 12px 14px; border: 1px solid var(--line); border-radius: var(--radius); background: #fff; color: var(--ink); font-size: 1rem; }\n#player-search:focus { outline: 3px solid var(--focus); border-color: var(--teal); }\n.player-suggestions { position: absolute; z-index: 10; top: 76px; left: 0; right: 0; max-height: 230px; overflow: auto; background: #fff; border: 1px solid var(--line); box-shadow: 0 10px 25px rgba(24, 35, 43, .12); }\n.player-suggestions[hidden] { display: none; }\n.player-suggestion { display: block; width: 100%; padding: 11px 14px; border: 0; border-bottom: 1px solid #eee; background: #fff; color: var(--ink); text-align: left; cursor: pointer; }\n.player-suggestion:hover { background: #e7f1ed; color: var(--teal); }\n.suggestion-empty { padding: 12px 14px; color: var(--muted); font-style: italic; }\n.selected-player-chips { display: flex; flex-wrap: wrap; gap: var(--space-1); min-height: 46px; padding: var(--space-2) 0 var(--space-1); }\n.selection-chip { display: inline-flex; align-items: center; gap: 7px; padding: 6px 9px 6px 12px; border: 1px solid #c8ddd5; border-radius: 999px; background: #e6f0ec; }\n.selection-chip button { min-height: 28px; padding: 0 4px; border: 0; background: transparent; color: var(--teal); font-size: 1.1rem; cursor: pointer; }\n.selector-footer { display: flex; justify-content: space-between; align-items: center; gap: var(--space-2); color: var(--muted); font-size: .9rem; }\n.clear-players { padding: 4px 0; border: 0; background: transparent; color: var(--red); cursor: pointer; }\n\n.tables-grid, .history-tables { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: var(--space-2); }\n.table-card, .history-table { padding: var(--space-3); border: 1px solid var(--line); border-left: 3px solid var(--gold); background: var(--panel); border-radius: var(--radius); }\n.table-title, .history-table-title { margin-bottom: var(--space-2); font-weight: 700; }\n.player-grid { display: grid; grid-template-columns: 1fr; gap: var(--space-1); }.player-chip { display: flex; align-items: center; min-height: 42px; padding: 10px 8px; border: 1px solid #c8ddd5; background: #e6f0ec; font-weight: 500; }\n.player-chip.reserve { border-color: #ecd49b; background: #fff0cf; color: #805d1d; }\n.configuration { margin-top: var(--space-3); }\n.alternative { margin-top: var(--space-4); padding-top: var(--space-3); border-top: 1px solid var(--line); }\n.score-label { margin-bottom: var(--space-2); color: var(--teal); font-weight: 700; }\n\n.history-section-title { margin: var(--space-4) 0 var(--space-2); }\n.history-day { padding: var(--space-4) 0; border-top: 1px solid var(--line); }\n.history-header { display: flex; justify-content: space-between; align-items: center; gap: var(--space-2); }\n.history-header h3 { margin-bottom: 0; }\n.history-players { color: var(--muted); }\n.scores-button, .danger-button { padding: 9px 14px; border: 1px solid; cursor: pointer; }\n.scores-button { color: var(--teal); border-color: var(--teal); background: transparent; }\n.scores-button:hover { background: #e7f1ed; }\n.danger-button { color: var(--red); border-color: #dfaaa4; background: transparent; }\n.danger-button:hover { background: #f8e7e3; }\n\n.pairings-table, .data-table { width: 100%; border-collapse: collapse; background: var(--panel); }\n.standings-table tr.rank-gold, .data-table tr.rank-gold { background: #fbe9c9; }\n.standings-table tr.rank-silver, .data-table tr.rank-silver { background: #e9edf0; }\n.standings-table tr.rank-bronze, .data-table tr.rank-bronze { background: #f0ddca; }\n.standings-table tr.rank-lantern, .data-table tr.rank-lantern { background: #f8e0dd; }\n.pairings-table th, .pairings-table td, .data-table th, .data-table td { padding: 12px 13px; border-bottom: 1px solid var(--line); text-align: left; }\n.pairings-table th, .data-table th { color: var(--teal); font-family: 'Space Grotesk', sans-serif; white-space: nowrap; }\n.pairings-table th:last-child, .pairings-table .pair-count, .data-table .numeric { text-align: left; font-weight: 700; }\n.data-table .score-winner { color: var(--ink); }\n.data-table .score-loser { color: var(--muted); font-weight: 400; }\n.table-scroll { max-width: 100%; overflow-x: auto; -webkit-overflow-scrolling: touch; }\n.data-table { min-width: 520px; }\n\n.score-table-card { padding: var(--space-4) 0; border-top: 1px solid var(--line); }\n.score-table-card h3 { margin-bottom: var(--space-2); }\n.score-game { display: grid; grid-template-columns: 70px minmax(140px, 1fr) 100px 32px 100px minmax(140px, 1fr); align-items: center; gap: var(--space-2); margin: var(--space-1) 0; padding: var(--space-2); background: var(--surface); }\n.score-game .form-group { margin: 0; }\n.score-game-title { font-weight: 700; }\n.score-team { font-weight: 500; }\n.score-vs { color: var(--muted); text-align: center; font-weight: 700; }\n.score-warning, .score-error, .status { margin: var(--space-2) 0; padding: 12px 14px; border-left: 4px solid var(--teal); background: #e7f1ed; }\n.score-warning { color: #805d1d; border-color: var(--gold); background: #fff0cf; }\n.score-error, .error-status { color: #7e2f2a; border-color: var(--red); background: #f8e7e3; }\n.empty-state { padding: var(--space-2) 0; color: var(--muted); }\n\n.mirror-navigation-group { position: relative; z-index: 1001; }\n.mirror-navigation-group + .app-shell { padding-top: 132px; }\n.mobile-nav-bar { display: flex; position: fixed; inset: 0 0 auto; z-index: 1001; justify-content: space-between; align-items: center; min-height: 58px; padding: 0 max(24px, calc((100% - 1180px) / 2 + 24px)); background: rgba(244, 241, 234, .97); border-bottom: 1px solid var(--line); box-shadow: 0 5px 14px rgba(24, 35, 43, .08); }\n.mobile-nav-brand { color: var(--teal); font-family: 'Space Grotesk', sans-serif; font-size: 1.15rem; font-weight: 700; }\n.mobile-nav-toggle { display: none; }\n.mobile-nav-toggle { min-width: 48px; padding: 8px 12px; border: 1px solid var(--line); background: var(--panel); color: var(--ink); cursor: pointer; }\n.mobile-nav-toggle { align-items: center; justify-content: center; }\n.hamburger-icon { display: block; position: relative; width: 22px; height: 16px; border-top: 2px solid currentColor; border-bottom: 2px solid currentColor; }\n.hamburger-icon::after { content: ''; position: absolute; top: 5px; left: 0; right: 0; border-top: 2px solid currentColor; }\n.mirror-navigation-group > .nav-tabs { position: fixed; top: 58px; left: 0; right: 0; z-index: 1000; padding: 0 max(24px, calc((100% - 1180px) / 2 + 24px)); background: rgba(244, 241, 234, .97); }\n\n@media (max-width: 760px) {\n  .app-shell { padding: var(--space-4) 14px 52px; }\n  .panel { padding: var(--space-3); }\n  .score-game { grid-template-columns: 1fr 1fr; }\n  .score-game-title { grid-column: 1 / -1; }\n  .score-vs { display: none; }\n}\n@media (max-width: 600px) {\n  .mirror-navigation-group + .app-shell { padding-top: calc(var(--space-4) + 52px); }\n  .intro { padding-top: var(--space-2); }\n  .intro h1 { font-size: clamp(2rem, 11vw, 3.1rem); }\n  .history-header { align-items: flex-start; flex-direction: column; }\n  .history-header button { width: 100%; }\n  .history-tables { display: block; }\n  .history-table { margin-bottom: var(--space-2); }\n  .player-grid { gap: 6px; }\n  .app-shell > .nav-tabs { display: flex !important; flex-wrap: nowrap; overflow-x: auto; }\n  .mobile-nav-bar { min-height: 52px; padding: 0 14px; }\n  .mobile-nav-toggle { display: inline-flex; }\n  .mirror-navigation-group .nav-tabs::before { display: none; }\n  .mirror-navigation-group > .nav-tabs { display: none; position: fixed; top: 52px; left: 14px; right: 14px; z-index: 1000; margin: 0; padding: 0; overflow: visible; background: transparent; }\n  .mirror-navigation-group.is-open > .nav-tabs { display: flex; flex-direction: column; flex-wrap: nowrap; padding: 6px 0; border: 1px solid var(--line); background: var(--panel); box-shadow: 0 8px 20px rgba(24, 35, 43, .16); }\n  .mirror-navigation-group > .tab-content { padding-top: 52px; }\n  .mirror-navigation-group .nav-tabs .nav-link { width: 100%; min-height: 46px; padding: 13px 12px; white-space: normal; }\n  .table-scroll { width: 100%; overflow-x: auto; }\n  .data-table { min-width: 560px; }\n  .pairings-table { min-width: 380px; }\n}\n"


def _history_dates():
    return sorted(load_pairing_history(HISTORY_FILE), reverse=True)


def _scores_input_id(play_date):
    return f"mirror_scores_{play_date.replace('-', '_')}"


def _history_view():
    history = load_pairing_history(HISTORY_FILE)
    if not history:
        return ui.div("Nog geen speeldagen gevonden.", class_="empty-state")
    today = date.today().isoformat()
    future_dates = sorted(item for item in history if item > today)
    played_dates = sorted((item for item in history if item <= today), reverse=True)
    sections = []
    if future_dates:
        sections.append(ui.h2("Toekomstige speeldag", class_="history-section-title"))
    for play_date in future_dates + played_dates:
        reserve_names = load_reserve_assignments(RESERVE_ASSIGNMENTS_FILE).get(
            play_date, {}
        )
        tables = []
        for table, players in history[play_date]:
            tables.append(
                ui.div(
                    ui.div(f"Tafel {table}", class_="history-table-title"),
                    ui.div(
                        *[
                            ui.div(
                                html.escape(reserve_names.get(player, player)),
                                class_=(
                                    "player-chip reserve"
                                    if player.startswith("Reserve ")
                                    else "player-chip"
                                ),
                            )
                            for player in players
                        ],
                        class_="player-grid",
                    ),
                    class_="history-table",
                )
            )
        sections.append(
            ui.tags.section(
                ui.div(
                    ui.h3(play_date),
                    ui.tags.button(
                        "Scores",
                        type="button",
                        class_="scores-button",
                        onclick=f"window.Shiny.setInputValue('score_navigation', '{play_date}', {{priority:'event'}})",
                    ),
                    class_="history-header",
                ),
                ui.div(*tables, class_="history-tables"),
                class_="history-day",
            )
        )
        if played_dates and play_date == played_dates[0]:
            sections.insert(
                len(sections) - 1,
                ui.h2("Gespeelde dagen", class_="history-section-title"),
            )
    return ui.div(*sections)


def _scores_view(play_date=None, selected_player=""):
    rows = load_scores(str(SCORES_FILE), play_date or None)
    if selected_player:
        rows = [
            row for row in rows
            if selected_player.casefold() in row["Team1Players"].casefold()
            or selected_player.casefold() in row["Team2Players"].casefold()
        ]
    if not rows:
        return ui.div("Nog geen scores gevonden.", class_="empty-state")

    table_rows = []
    for row in rows:
        team1_score, team2_score = row["Team1Score"], row["Team2Score"]
        team1_won = team1_score > team2_score
        table_rows.append(ui.tags.tr(
            ui.tags.td(str(row["Date"])), ui.tags.td(str(row["Table"])), ui.tags.td(str(row["Game"])),
            ui.tags.td(row["Team1Players"].replace("|", " + "), class_="numeric score-winner" if team1_won else "numeric score-loser"),
            ui.tags.td(str(team1_score), class_="numeric score-winner" if team1_won else "numeric score-loser"),
            ui.tags.td(row["Team2Players"].replace("|", " + "), class_="numeric score-loser" if team1_won else "numeric score-winner"),
            ui.tags.td(str(team2_score), class_="numeric score-loser" if team1_won else "numeric score-winner"),
        ))

    return ui.div(ui.tags.table(
        ui.tags.thead(ui.tags.tr(
            ui.tags.th("Datum"), ui.tags.th("Tafel"), ui.tags.th("Spel"), ui.tags.th("Team 1"),
            ui.tags.th("Score"), ui.tags.th("Team 2"), ui.tags.th("Score"),
        )),
        ui.tags.tbody(*table_rows), class_="data-table"
    ), class_="table-scroll")

def _standings_view(play_date=None):
    rows = compute_standings(str(SCORES_FILE), play_date or None)
    if not rows:
        return ui.div("Nog geen scores gevonden.", class_="empty-state")

    medal_classes = {0: "rank-gold", 1: "rank-silver", 2: "rank-bronze"}
    medal_emojis = {0: "🥇", 1: "🥈", 2: "🥉"}
    active_indices = [i for i, row in enumerate(rows) if row["games_played"] > 0]
    last_active_index = active_indices[-1] if active_indices else None

    table_rows = []
    for index, row in enumerate(rows):
        row_classes = []
        emoji = ""
        if index in medal_classes:
            row_classes.append(medal_classes[index])
            emoji = medal_emojis[index]
        elif index == last_active_index:
            row_classes.append("rank-lantern")
            emoji = "🏮"

        player_display = f"{emoji} {row['player']}" if emoji else row["player"]
        tr_kwargs = {"class_": " ".join(row_classes)} if row_classes else {}

        table_rows.append(
            ui.tags.tr(
                ui.tags.td(str(index + 1)),
                ui.tags.td(player_display),
                ui.tags.td(str(row["wins"])),
                ui.tags.td(str(row["games_played"])),
                ui.tags.td(str(row["points_for"]), class_="numeric"),
                ui.tags.td(str(row["points_against"]), class_="numeric"),
                ui.tags.td(str(row["point_diff"]), class_="numeric"),
                **tr_kwargs,
            )
        )

    return ui.div(
        ui.tags.table(
            ui.tags.thead(
                ui.tags.tr(
                    ui.tags.th("#"),
                    ui.tags.th("Speler"),
                    ui.tags.th("Gewonnen"),
                    ui.tags.th("Gespeeld"),
                    ui.tags.th("Voor"),
                    ui.tags.th("Tegen"),
                    ui.tags.th("Saldo"),
                )
            ),
            ui.tags.tbody(*table_rows),
            class_="data-table",
        ),
        class_="table-scroll",
    )


def _pairings_view(selected_player=""):
    rows = [row for row in load_pairing_counts(PAIRINGS_FILE) if row[2] > 0]
    if selected_player:
        rows = [
            row
            for row in rows
            if selected_player.casefold() in row[0].casefold()
            or selected_player.casefold() in row[1].casefold()
        ]
    rows.sort(key=lambda row: (-row[2], row[0].casefold(), row[1].casefold()))
    if not rows:
        return ui.div("Geen paringen gevonden.", class_="empty-state")
    return ui.div(
        ui.tags.table(
            ui.tags.thead(
                ui.tags.tr(
                    ui.tags.th("Speler 1"),
                    ui.tags.th("Speler 2"),
                    ui.tags.th("Samen gespeeld"),
                )
            ),
            ui.tags.tbody(
                *[
                    ui.tags.tr(
                        ui.tags.td(a),
                        ui.tags.td(b),
                        ui.tags.td(str(count), class_="numeric"),
                    )
                    for a, b, count in rows
                ]
            ),
            class_="data-table",
        ),
        class_="table-scroll",
    )


players = sorted(
    {player for rows in load_pairing_counts(PAIRINGS_FILE) for player in rows[:2]},
    key=str.casefold,
)
history_choices = {item: item for item in _history_dates()}

app_ui = ui.page_fluid(
    ui.tags.head(
        ui.tags.meta(name="viewport", content="width=device-width, initial-scale=1"),
        ui.tags.title("Manillen | Publieke mirror"),
        ui.tags.style(APP_CSS),
    ),
    ui.div(
        ui.div(
            ui.div("Manillen | Publieke mirror", class_="mobile-nav-brand"),
            ui.tags.button(
                ui.tags.span(class_="hamburger-icon", aria_hidden="true"),
                id="mobile-nav-toggle",
                type="button",
                class_="mobile-nav-toggle",
                aria_label="Open navigatie",
                aria_expanded="false",
            ),
            class_="mobile-nav-bar",
        ),
        ui.navset_tab(
            ui.nav_panel(
                "Tussenstand",
                ui.div(
                    ui.h2("Tussenstand"),
                    ui.input_select(
                        "standings_date",
                        "Periode",
                        {"": "Alle speeldagen (cumulatief)", **history_choices},
                    ),
                    ui.output_ui("standings"),
                    class_="panel",
                ),
            ),
            ui.nav_panel(
                "Speeldagen",
                ui.div(ui.h2("Speeldagen"), ui.output_ui("history"), class_="panel"),
            ),
            ui.nav_panel(
                "Scores",
                ui.div(
                    ui.h2("Scores"),
                    ui.input_select(
                        "scores_date",
                        "Speeldag",
                        {"": "Alle speeldagen", **history_choices},
                    ),
                    ui.input_selectize(
                        "scores_player",
                        "Filter op speler",
                        choices={
                            "": "Alle spelers",
                            **{player: player for player in players},
                        },
                        selected="",
                        options={
                            "placeholder": "Typ een naam...",
                            "allowEmptyOption": True,
                        },
                    ),
                    ui.output_ui("scores"),
                    class_="panel",
                ),
            ),
            ui.nav_panel(
                "Parenhistoriek",
                ui.div(
                    ui.h2("Parenhistoriek"),
                    ui.input_selectize(
                        "pairing_player",
                        "Zoek speler",
                        choices={
                            "": "Alle spelers",
                            **{player: player for player in players},
                        },
                        selected="",
                        options={
                            "placeholder": "Typ een naam...",
                            "allowEmptyOption": True,
                        },
                    ),
                    ui.output_ui("pairings"),
                    class_="panel",
                ),
            ),
            id="tabs",
            selected="Tussenstand",
        ),
        ui.tags.script("""
            (() => {
                const init = () => {
                    const group = document.querySelector('.mirror-navigation-group');
                    const button = document.querySelector('#mobile-nav-toggle');
                    if (!group || !button || group.dataset.ready === 'true') return;
                    group.dataset.ready = 'true';
                    const close = () => {
                        group.classList.remove('is-open');
                        button.setAttribute('aria-expanded', 'false');
                        button.setAttribute('aria-label', 'Open navigatie');
                    };
                    button.addEventListener('click', () => {
                        const isOpen = group.classList.toggle('is-open');
                        button.setAttribute('aria-expanded', String(isOpen));
                        button.setAttribute('aria-label', isOpen ? 'Sluit navigatie' : 'Open navigatie');
                    });
                    group.querySelectorAll('.nav-link').forEach((link) => link.addEventListener('click', close));
                };
                if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
            })();
        """),
        class_="mirror-navigation-group",
    ),
    ui.div(
        ui.div("MANILLEN / PUBLIEKE MIRROR", class_="eyebrow"),
        ui.h1("Manillen before dark: de speeldagen, helder bijgehouden."),
        ui.p(
            "Een actuele, alleen-lezen momentopname van speeldagen, tussenstand en parenhistoriek."
        ),
        class_="intro",
    ),
    class_="app-shell",
)


def server(input: Inputs, output: Outputs, session: Session):
    refresh = reactive.Value(0)

    @render.ui
    def history():
        refresh()
        return _history_view()

    @render.ui
    def standings():
        refresh()
        return _standings_view(input.standings_date() or None)

    @render.ui
    def scores():
        refresh()
        return _scores_view(input.scores_date() or None, input.scores_player() or "")

    @reactive.effect
    @reactive.event(input.score_navigation)
    def scores_navigation():
        play_date = input.score_navigation()
        ui.update_select("scores_date", selected=play_date)
        ui.update_navset("tabs", selected="Scores")

    @render.ui
    def pairings():
        refresh()
        return _pairings_view(input.pairing_player() or "")


app = App(app_ui, server)

"""Pure CSV readers shared by the NAS app and the read-only mirror."""

import csv
from collections import defaultdict
from pathlib import Path


def load_pairing_history(history_filename):
    """Return history grouped by date as ``{date: [(table, players), ...]}``."""
    grouped = defaultdict(list)
    path = Path(history_filename)
    if not path.exists():
        return {}
    with path.open("r", encoding="utf-8", newline="") as file:
        for row in csv.DictReader(file):
            players = [name.strip() for name in row.get("Players", "").split("|")]
            if len(players) != 4 or not row.get("Date"):
                continue
            try:
                table = int(row.get("Table", ""))
            except (TypeError, ValueError):
                continue
            grouped[row["Date"].strip()].append((table, players))
    return {
        play_date: sorted(tables, key=lambda item: item[0])
        for play_date, tables in grouped.items()
    }


def load_pairing_counts(pairings_filename):
    """Return valid pairing rows as ``[(player1, player2, count), ...]``."""
    path = Path(pairings_filename)
    if not path.exists():
        return []
    rows = []
    with path.open("r", encoding="utf-8", newline="") as file:
        for row in csv.DictReader(file):
            try:
                count = int(row.get("Count", 0))
            except (TypeError, ValueError):
                continue
            player1 = row.get("Player1", "").strip()
            player2 = row.get("Player2", "").strip()
            if player1 and player2 and count >= 0:
                rows.append((player1, player2, count))
    return rows


def load_reserve_assignments(assignments_filename):
    """Return saved reserve names grouped by date and reserve slot."""
    path = Path(assignments_filename)
    if not path.exists():
        return {}
    assignments = defaultdict(dict)
    with path.open("r", encoding="utf-8", newline="") as file:
        for row in csv.DictReader(file):
            play_date = row.get("Date", "").strip()
            slot = row.get("Slot", "").strip()
            name = row.get("Name", "").strip()
            if play_date and slot and name:
                assignments[play_date][slot] = name
    return dict(assignments)

"""Pure score loading and standings logic shared with the NAS app."""

import csv
from collections import defaultdict
from datetime import date
from pathlib import Path


DEFAULT_SCORES_FILE = Path(__file__).resolve().parent / "data" / "scores_history.csv"


def _score_date(play_date):
    if play_date is None:
        return date.today().isoformat()
    if isinstance(play_date, date):
        return play_date.isoformat()
    if isinstance(play_date, str):
        try:
            return date.fromisoformat(play_date).isoformat()
        except ValueError:
            pass
        if len(play_date) == 8 and play_date.isdigit():
            return f"{play_date[:4]}-{play_date[4:6]}-{play_date[6:]}"
    raise ValueError("play_date must be a date or string in YYYY-MM-DD / YYYYMMDD format")


def load_scores(scores_filename=str(DEFAULT_SCORES_FILE), play_date=None):
    selected_date = _score_date(play_date) if play_date is not None else None
    path = Path(scores_filename)
    if not path.exists():
        return []
    rows = []
    with path.open("r", encoding="utf-8", newline="") as file:
        for row in csv.DictReader(file):
            if selected_date is not None and row.get("Date") != selected_date:
                continue
            try:
                row["Table"] = int(row["Table"])
                row["Game"] = int(row["Game"])
                row["Team1Score"] = int(row["Team1Score"])
                row["Team2Score"] = int(row["Team2Score"])
            except (TypeError, ValueError, KeyError):
                continue
            rows.append(row)
    return rows


def compute_standings(scores_filename=str(DEFAULT_SCORES_FILE), play_date=None):
    standings = defaultdict(lambda: {"games_played": 0, "wins": 0, "points_for": 0, "points_against": 0})
    for row in load_scores(scores_filename, play_date):
        team1 = [name.strip() for name in row["Team1Players"].split("|") if name.strip()]
        team2 = [name.strip() for name in row["Team2Players"].split("|") if name.strip()]
        if len(team1) != 2 or len(team2) != 2:
            continue
        scores = (row["Team1Score"], row["Team2Score"])
        for team_index, team in enumerate((team1, team2)):
            points_for, points_against = scores[team_index], scores[1 - team_index]
            for player in team:
                item = standings[player]
                item["games_played"] += 1
                item["wins"] += int(points_for > points_against)
                item["points_for"] += points_for
                item["points_against"] += points_against
    return sorted([
        {"player": player, **values, "point_diff": values["points_for"] - values["points_against"]}
        for player, values in standings.items()
    ], key=lambda row: (-row["wins"], -row["games_played"], -row["point_diff"], row["player"].casefold()))
